// Filter articles from the last 7 days (workflow runs every Monday)
// RSS feed structure: { title, link, pubDate (RFC 2822 format), content }
const items = $input.all();
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

const recentArticles = items.filter(item => {
  const article = item.json;
  // RSS feed uses 'pubDate' field in RFC 2822 format: "Tue, 29 Mar 2022 00:00:00 GMT"
  const pubDateStr = article.pubDate || article.published || article.isoDate || '';

  if (!pubDateStr) {
    // Skip articles without dates
    return false;
  }

  try {
    // JavaScript Date constructor can parse RFC 2822 format
    const pubDate = new Date(pubDateStr);

    // Check if date is valid
    if (isNaN(pubDate.getTime())) {
      return false; // Invalid date
    }

    // Return true if article was published within the last 7 days
    return pubDate >= sevenDaysAgo;
  } catch (e) {
    // If date parsing fails, exclude it to be safe
    console.log('Date parsing failed for article:', article.title, 'Date:', pubDateStr);
    return false;
  }
});

return recentArticles;

// Prepare filtered articles for AI selection
// RSS feed structure: { title, link, pubDate, content }
const items = $input.all();
const allArticles = items.map(item => {
  const article = item.json;

  // Extract description from content (remove HTML tags)
  let description = '';
  if (article.content) {
    // Remove HTML tags and get first 300 characters
    description = article.content.replace(/<[^>]*>/g, '').substring(0, 300).trim();
  } else if (article.contentSnippet) {
    description = article.contentSnippet.substring(0, 300);
  } else if (article.description) {
    description = article.description.substring(0, 300);
  }

  return {
    title: article.title || 'Untitled',
    url: article.link || article.url || '', // RSS uses 'link'
    description: description,
    published: article.pubDate || article.published || article.isoDate || '', // RSS uses 'pubDate'
    fullData: article
  };
});

return [{ json: { allArticles, totalCount: allArticles.length } }];

// Parse AI response and get top 5 articles
const aiResponse = $input.first().json;
const allArticlesData = $('Prepare Articles for AI').first().json;
const allArticles = allArticlesData.allArticles || [];

// Extract JSON from AI response (Groq/OpenAI format)
let aiSelectedArticles = [];
try {
  let content = '';

  // Handle Groq/OpenAI format: { choices: [{ message: { content: "..." } }] }
  if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
    content = aiResponse.choices[0].message.content || '';
  } else if (aiResponse.message) {
    content = aiResponse.message.content || aiResponse.message || '';
  }

  // Clean up content (remove markdown code blocks if present)
  content = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

  // Try to extract JSON from the response
  const jsonMatch = content.match(/\[\s*\{[\s\S]*\}\s*\]/);
  if (jsonMatch) {
    aiSelectedArticles = JSON.parse(jsonMatch[0]);
  } else {
    // Try parsing the whole content
    aiSelectedArticles = JSON.parse(content);
  }
} catch (e) {
  // If AI fails, fallback to first 5 articles
  console.log('AI parsing failed, using fallback:', e.message);
  aiSelectedArticles = allArticles.slice(0, 5).map(a => ({
    title: a.title,
    url: a.url,
    reason: 'Selected by fallback (AI unavailable)'
  }));
}

// Merge AI selection with full article data
const top5Articles = aiSelectedArticles.map(aiArticle => {
  // Find the full article data
  const fullArticle = allArticles.find(a => 
    (a.url && aiArticle.url && a.url === aiArticle.url) ||
    (a.title && aiArticle.title && a.title.toLowerCase() === aiArticle.title.toLowerCase())
  ) || aiArticle;

  return {
    ...fullArticle.fullData || fullArticle,
    aiReason: aiArticle.reason || 'Selected by AI'
  };
});

return [{ json: { articles: top5Articles, count: top5Articles.length } }];
